cat > /tmp/audit.mjs <<'EOF'
import { chromium } from '/Users/yuvalt/personal/visual-renderer/bench/versus-browser/tooling/node_modules/playwright/index.mjs';
const dir = process.argv[2];
const sizes = [['square',1080,1080],['landscape',1920,1080],['story',1080,1920]];
const b = await chromium.launch();
for (const [name,w,h] of sizes) {
  const p = await b.newPage({ viewport:{width:w,height:h} });
  await p.goto('file://'+dir+'/card.html');
  await p.evaluate(()=>document.fonts.ready);
  const r = await p.evaluate(({w,h})=>{
    const out={docScroll:[document.documentElement.scrollWidth,document.documentElement.scrollHeight],issues:[],boxes:{}};
    const sel={brand:'.brand',logo:'.brand img',eventName:'.brand span',portrait:'.portrait',name:'.speaker h2',role:'.speaker p',kicker:'.kicker',title:'.title',meta:'.meta',btn:'.btn'};
    for(const [k,s] of Object.entries(sel)){
      const e=document.querySelector(s); const b=e.getBoundingClientRect();
      out.boxes[k]=[+b.x.toFixed(1),+b.y.toFixed(1),+b.width.toFixed(1),+b.height.toFixed(1)];
      if(b.left<-0.5||b.top<-0.5||b.right>w+0.5||b.bottom>h+0.5) out.issues.push(`${k} outside viewport: ${JSON.stringify(out.boxes[k])}`);
      if(e.scrollWidth>Math.ceil(e.clientWidth)+1) out.issues.push(`${k} h-clip ${e.scrollWidth}>${e.clientWidth}`);
      if(e.scrollHeight>Math.ceil(e.clientHeight)+1&&k!=='portrait') out.issues.push(`${k} v-clip ${e.scrollHeight}>${e.clientHeight}`);
    }
    const pr=document.querySelector('.portrait').getBoundingClientRect();
    if(Math.abs(pr.width-pr.height)>0.5) out.issues.push(`portrait not square ${pr.width}x${pr.height}`);
    // overlap among text blocks
    const keys=['brand','portrait','name','role','kicker','title','meta','btn'];
    for(let i=0;i<keys.length;i++)for(let j=i+1;j<keys.length;j++){
      const a=out.boxes[keys[i]],c=out.boxes[keys[j]];
      if(['name','role','kicker'].includes(keys[i])&&['name','role','kicker'].includes(keys[j]))continue;
      const ox=Math.min(a[0]+a[2],c[0]+c[2])-Math.max(a[0],c[0]);
      const oy=Math.min(a[1]+a[3],c[1]+c[3])-Math.max(a[1],c[1]);
      if(ox>2&&oy>2) out.issues.push(`overlap ${keys[i]}/${keys[j]} ${ox.toFixed(1)}x${oy.toFixed(1)}`);
    }
    out.titleLines=Math.round(document.querySelector('.title').getBoundingClientRect().height/(parseFloat(getComputedStyle(document.querySelector('.title')).lineHeight)));
    out.font=getComputedStyle(document.querySelector('.title')).fontFamily;
    return out;
  },{w,h});
  console.log('==',name,w+'x'+h,'| docScroll',r.docScroll.join('x'),'| titleLines',r.titleLines,'| font',r.font);
  console.log('   issues:', r.issues.length?r.issues:'NONE');
  await p.close();
}
await b.close();
EOF
